css:
.chair-sim-container{padding:28px;background:#eef0f4;min-height:100vh;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1a2744}
.chair-sim-container h1,.chair-sim-container h3,.chair-sim-container p,.chair-sim-container div,.chair-sim-container span,.chair-sim-container strong,.chair-sim-container label{font-family:inherit}
.chair-sim-container .chair-sim-header{position:relative;background:#0f1d3d;color:#f5f7fb;padding:28px 32px 24px;border-radius:4px;margin-bottom:24px;box-shadow:0 4px 18px rgba(15,29,61,0.18);overflow:hidden}
.chair-sim-container .chair-sim-header-bar{position:absolute;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,#c8a96a 0%,#c8a96a 33%,#7e9bb8 33%,#7e9bb8 66%,#9c2b3a 66%,#9c2b3a 100%)}
.chair-sim-container .chair-sim-header-top{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;flex-wrap:wrap}
.chair-sim-container .chair-sim-eyebrow{font-size:0.72rem;letter-spacing:0.18em;text-transform:uppercase;color:#c8a96a;margin-bottom:8px;font-weight:600}
.chair-sim-container .chair-sim-header h1{font-size:1.65rem;font-weight:600;margin:0 0 6px;letter-spacing:-0.01em;color:#fff}
.chair-sim-container .chair-sim-subtitle{font-size:0.92rem;color:#b8c2d6;font-weight:400}
.chair-sim-container .chair-sim-meta{text-align:right;min-width:220px}
.chair-sim-container .chair-sim-meta-row{font-size:0.85rem;color:#b8c2d6;margin-bottom:4px}
.chair-sim-container .chair-sim-meta-row strong{color:#fff;font-size:1.1rem;font-weight:600}
.chair-sim-container .chair-sim-meta-moment{font-size:0.78rem;color:#c8a96a;text-transform:uppercase;letter-spacing:0.1em;margin-top:6px;font-weight:600}
.chair-sim-container .chair-sim-briefing{background:#fff;border-left:3px solid #c8a96a;padding:22px 28px;margin-bottom:24px;border-radius:2px;box-shadow:0 1px 3px rgba(15,29,61,0.06)}
.chair-sim-container .chair-sim-briefing-label{font-size:0.7rem;letter-spacing:0.16em;text-transform:uppercase;color:#7d6737;font-weight:700;margin-bottom:10px}
.chair-sim-container .chair-sim-briefing-body{font-size:0.95rem;line-height:1.65;color:#2d3a5b}
.chair-sim-container .chair-sim-briefing-body strong{color:#0f1d3d}
.chair-sim-container .chair-sim-status-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin-bottom:28px}
.chair-sim-container .chair-sim-status-card{background:#fff;padding:18px 18px 16px;border-radius:2px;border-left:3px solid #cbd2e0;box-shadow:0 1px 3px rgba(15,29,61,0.05);transition:transform 0.18s ease,box-shadow 0.18s ease}
.chair-sim-container .chair-sim-status-card:hover{transform:translateY(-2px);box-shadow:0 4px 14px rgba(15,29,61,0.1)}
.chair-sim-container .chair-sim-status-label{font-size:0.7rem;letter-spacing:0.14em;text-transform:uppercase;color:#5a6685;font-weight:600;margin-bottom:8px}
.chair-sim-container .chair-sim-status-value{font-size:2.1rem;font-weight:700;color:#0f1d3d;line-height:1;margin-bottom:6px;letter-spacing:-0.02em}
.chair-sim-container .chair-sim-status-hint{font-size:0.75rem;color:#61697a;line-height:1.4}
.chair-sim-container .chair-sim-card-intrusion{border-left-color:#9c2b3a}
.chair-sim-container .chair-sim-card-intrusion .chair-sim-status-value{color:#9c2b3a}
.chair-sim-container .chair-sim-card-omission{border-left-color:#a15b1f}
.chair-sim-container .chair-sim-card-omission .chair-sim-status-value{color:#b86825}
.chair-sim-container .chair-sim-card-channel{border-left-color:#6b4e8a}
.chair-sim-container .chair-sim-card-channel .chair-sim-status-value{color:#6b4e8a}
.chair-sim-container .chair-sim-card-cohesion{border-left-color:#1f5e75}
.chair-sim-container .chair-sim-card-cohesion .chair-sim-status-value{color:#1f5e75}
.chair-sim-container .chair-sim-card-procedure{border-left-color:#0f6e4f}
.chair-sim-container .chair-sim-card-procedure .chair-sim-status-value{color:#0f6e4f}
.chair-sim-container .chair-sim-controls{background:#fff;padding:26px 28px 24px;border-radius:2px;margin-bottom:24px;box-shadow:0 1px 3px rgba(15,29,61,0.06);border-top:3px solid #0f1d3d}
.chair-sim-container .chair-sim-section-title{font-size:1.05rem;font-weight:600;color:#0f1d3d;margin:0 0 6px;letter-spacing:-0.005em}
.chair-sim-container .chair-sim-section-hint{font-size:0.85rem;color:#5a6685;margin:0 0 18px;line-height:1.5}
.chair-sim-container .chair-sim-decisions-panel{display:flex;flex-direction:column;gap:18px;margin-bottom:24px}
.chair-sim-container .chair-sim-decision-row{display:flex;flex-direction:column;gap:8px;padding:16px 18px;background:#f7f9fc;border:1px solid #e3e7ef;border-radius:2px}
.chair-sim-container .chair-sim-decision-row:hover{border-color:#c8a96a}
.chair-sim-container .chair-sim-decision-label{font-size:0.92rem;font-weight:600;color:#0f1d3d;line-height:1.4}
.chair-sim-container .chair-sim-decision-select{width:100%;padding:10px 12px;background:#fff;color:#1a2744;border:1px solid #c5cdde;border-radius:2px;font-size:0.9rem;font-family:inherit;cursor:pointer}
.chair-sim-container .chair-sim-decision-select:focus{outline:none;border-color:#c8a96a;box-shadow:0 0 0 2px rgba(200,169,106,0.2)}
.chair-sim-container .chair-sim-decision-select option{background:#fff;color:#1a2744;padding:6px}
.chair-sim-container .chair-sim-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding-top:8px;border-top:1px solid #eef0f4}
.chair-sim-container .chair-sim-actions .btn{padding:10px 22px;font-size:0.92rem;font-weight:600;border-radius:2px;font-family:inherit;letter-spacing:0.01em;border-width:1px}
.chair-sim-container .chair-sim-actions .btn-primary{background:#0f1d3d;border-color:#0f1d3d;color:#fff}
.chair-sim-container .chair-sim-actions .btn-primary:hover{background:#1a2744;border-color:#1a2744}
.chair-sim-container .chair-sim-actions .btn-outline-secondary{background:#fff;border-color:#c5cdde;color:#5a6685}
.chair-sim-container .chair-sim-actions .btn-outline-secondary:hover{background:#f7f9fc;border-color:#5a6685;color:#0f1d3d}
.chair-sim-container .chair-sim-tools-block{background:#fff;padding:26px 28px;border-radius:2px;margin-bottom:24px;box-shadow:0 1px 3px rgba(15,29,61,0.06);border-top:3px solid #c8a96a}
.chair-sim-container .chair-sim-chart-wrapper{height:340px;position:relative;margin-top:8px}
.chair-sim-container .chair-sim-history{background:#fff;padding:26px 28px;border-radius:2px;box-shadow:0 1px 3px rgba(15,29,61,0.06);border-top:3px solid #1f5e75;margin-bottom:24px}
.chair-sim-container .chair-sim-history table{margin-top:12px;font-size:0.88rem;color:#1a2744}
.chair-sim-container .chair-sim-history table th{background:#f7f9fc;color:#0f1d3d;font-weight:600;text-transform:uppercase;letter-spacing:0.06em;font-size:0.7rem;padding:10px 12px;border-top:none;border-bottom:2px solid #e3e7ef}
.chair-sim-container .chair-sim-history table td{padding:10px 12px;border-top:1px solid #eef0f4;color:#2d3a5b}
.chair-sim-container .chair-sim-history table tr:hover td{background:#f7f9fc}
@media(max-width:768px){.chair-sim-container{padding:16px}
.chair-sim-container .chair-sim-header{padding:22px 20px}
.chair-sim-container .chair-sim-header h1{font-size:1.25rem}
.chair-sim-container .chair-sim-header-top{flex-direction:column;align-items:flex-start}
.chair-sim-container .chair-sim-meta{text-align:left}
.chair-sim-container .chair-sim-status-grid{grid-template-columns:repeat(2,1fr)}
.chair-sim-container .chair-sim-status-value{font-size:1.6rem}
.chair-sim-container .chair-sim-controls,.chair-sim-container .chair-sim-tools-block,.chair-sim-container .chair-sim-history,.chair-sim-container .chair-sim-briefing{padding:18px}
.chair-sim-container .chair-sim-chart-wrapper{height:280px}}

/* --- EQIL 2026-08-08: accessibility + debrief --- */
.chair-sim-container :focus-visible,
select:focus-visible, button:focus-visible {
    outline: 3px solid #1a4fb4;
    outline-offset: 2px;
    border-radius: 3px;
}
.chair-sim-decision-label { display: block; margin-bottom: 4px; font-weight: 600; }
.chair-sim-debrief {
    margin-top: 20px;
    padding: 20px 22px;
    background: #ffffff;
    border: 1px solid #d3d8e0;
    border-left: 4px solid #7d6737;
    border-radius: 6px;
    color: #1b2330;
}
.chair-sim-debrief h3 { margin: 0 0 8px; font-size: 18px; }
.chair-sim-debrief h4 { margin: 16px 0 6px; font-size: 12px; text-transform: uppercase; letter-spacing: .05em; color: #61697a; }
.chair-sim-debrief-band { margin: 0 0 10px; font-size: 15px; }
.chair-sim-debrief-kpis { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px 24px; }
.chair-sim-debrief-kpis li { display: flex; flex-direction: column; }
.chair-sim-debrief-kpis span { font-size: 12px; color: #61697a; }
.chair-sim-debrief-kpis strong { font-size: 18px; }
.chair-sim-debrief-insights { margin: 14px 0 0; padding-left: 20px; }
.chair-sim-debrief-insights li { margin-bottom: 8px; line-height: 1.55; }
@media (prefers-reduced-motion: reduce) {
    * { animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; }
}

/* --- EQIL 2026-11-12: contrast, turning point, discussion questions --- */
.chair-sim-container .chair-sim-card-omission .chair-sim-status-value{color:#a15b1f}
.chair-sim-debrief-turning { margin: 12px 0 0; padding: 10px 12px; background: #f7f9fc; border-left: 3px solid #9c2b3a; line-height: 1.5; }
.chair-sim-debrief-questions { margin: 6px 0 0; padding-left: 20px; }
.chair-sim-debrief-questions li { margin-bottom: 6px; line-height: 1.5; }

