    function currentLang() {
        var l = (window.vcI18n && window.vcI18n._lang) || document.documentElement.lang || 'en';
        l = String(l).substring(0, 2);
        return l === 'es' ? 'es' : 'en';
    }

    class ChairAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Chairman / Lead Director Playbook';
            this.version = '1.2.0';
            this.ROUNDS = ROUNDS;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    intrusions: 0,
                    omissions: 0,
                    soleChannel: 0,
                    cohesion: 100,
                    procedure: 100,
                    framing: 0,
                    sequencing: 0,
                    recusal: 0,
                    after: 0,
                    framingHistory: [],
                    sequencingHistory: [],
                    recusalHistory: [],
                    afterHistory: [],
                    intrusionsHistory: [],
                    omissionsHistory: [],
                    cohesionHistory: [],
                    procedureHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._bindRepaint();
            this._updateBriefing(state);
        }

        _bindRepaint() {
            /* repaint adapter-written text on a language switch, after a submit, an undo or a reload */
            if (this._repaintBound || !window.mySimulation) return;
            this._repaintBound = true;
            var self = this;
            var repaint = function() {
                try {
                    var st = window.mySimulation && window.mySimulation.state;
                    if (st) self._updateBriefing(st);
                } catch (e) { /* never break the page */ }
            };
            document.addEventListener('express:langchanged', repaint);
            var bus = window.mySimulation.eventBus;
            if (bus && typeof bus.on === 'function') {
                ['language:changed', 'period:submitted', 'period:undone', 'state:loaded'].forEach(function(ev) {
                    bus.on(ev, repaint);
                });
                /* undo rebuilds the round panel after the framework restored the inputs: let the
                   shared guard register the new controls now, before the player touches them, so
                   the same choices resubmitted replay the round exactly */
                bus.on('period:undone', function() {
                    try { if (typeof __eqilGuard !== 'undefined' && __eqilGuard && typeof __eqilGuard.pass === 'function') { __eqilGuard.pass(); } } catch (e) {}
                });
            }
        }

        _composite(ds, nRounds) {
            /* v1.2.0 calibration: tools 60 and hygiene 40 on their reachable ranges,
               minus a fault charge that rises with every intrusion, omission or
               sole-channel event: 40 x (1 - e^(-faults/8)), about 4.7 for the first. */
            var b = this._bounds(nRounds);
            var totalTools = (ds.framing || 0) + (ds.sequencing || 0) + (ds.recusal || 0) + (ds.after || 0);
            var span = (b.maxTools - b.minTools) || 1;
            var toolScore = Math.max(0, Math.min(100, ((totalTools - b.minTools) / span) * 100));
            var coh = typeof ds.cohesion === 'number' ? ds.cohesion : 100;
            var proc = typeof ds.procedure === 'number' ? ds.procedure : 100;
            var hSpan = (b.maxHyg - b.minHyg) || 1;
            var hygiene = Math.max(0, Math.min(100, ((coh + proc - 200 - b.minHyg) / hSpan) * 100));
            var faults = (ds.intrusions || 0) + (ds.omissions || 0) + (ds.soleChannel || 0);
            var faultPenalty = 40 * (1 - Math.exp(-faults / 8));
            return Math.max(0, Math.min(100,
                Math.round((toolScore * 0.6) + (hygiene * 0.4) - faultPenalty)));
        }

        _turningPoint(chosen, lang) {
            /* the decision of the run that cost the most against the best option of that decision */
            var b = this._bounds(this.ROUNDS.length);
            var tSpan = (b.maxTools - b.minTools) || 1, hSpan = (b.maxHyg - b.minHyg) || 1;
            var worst = null;
            var val = function(s) {
                s = s || {};
                var tools = (s.framing || 0) + (s.sequencing || 0) + (s.recusal || 0) + (s.after || 0);
                var hyg = (s.cohesion || 0) + (s.procedure || 0);
                var faults = (s.intrusion || 0) + (s.omission || 0) + (s.soleChannel || 0);
                return tools * 60 / tSpan + hyg * 40 / hSpan - faults * 5;
            };
            this.ROUNDS.forEach(function(round) {
                round.decisions.forEach(function(d) {
                    var v = chosen[d.id];
                    if (!v || !round.scoring[d.id]) return;
                    var best = null;
                    d.options.forEach(function(o) {
                        var x = val(round.scoring[d.id][o.value]);
                        if (best === null || x > best) best = x;
                    });
                    var loss = best - val(round.scoring[d.id][v]);
                    if (loss > 0.5 && (!worst || loss > worst.loss)) {
                        var opt = d.options.filter(function(o) { return o.value === v; })[0] || {};
                        worst = {
                            loss: loss,
                            moment: (lang === 'es' && round.momentTitleEs) ? round.momentTitleEs : round.momentTitle,
                            label: (lang === 'es' && d.labelEs) ? d.labelEs : d.label,
                            option: (lang === 'es' && opt.labelEs) ? opt.labelEs : opt.label
                        };
                    }
                });
            });
            return worst ? (worst.moment + ' — ' + worst.label + ': ' + worst.option) : '';
        }

        _bandOf(score) {
            if (score >= 90) return 'excellent';
            if (score >= 75) return 'solid';
            if (score >= 50) return 'developing';
            return 'apprentice';
        }

        _bounds(nRounds) {
            var n = Math.max(1, Math.min(this.ROUNDS.length, nRounds || this.ROUNDS.length));
            this._boundsCache = this._boundsCache || {};
            if (this._boundsCache[n]) return this._boundsCache[n];
            var maxTools = 0, minTools = 0, maxFaults = 0, maxHyg = 0, minHyg = 0;
            for (var r = 0; r < n; r++) {
                var round = this.ROUNDS[r];
                var sc = round.scoring || {};
                for (var i = 0; i < round.decisions.length; i++) {
                    var dec = round.decisions[i];
                    var bt = null, wt = null, wf = 0, bh = null, wh = null;
                    for (var k = 0; k < dec.options.length; k++) {
                        var s = (sc[dec.id] && sc[dec.id][dec.options[k].value]) || {};
                        var tools = (s.framing || 0) + (s.sequencing || 0) + (s.recusal || 0) + (s.after || 0);
                        var faults = (s.intrusion || 0) + (s.omission || 0) + (s.soleChannel || 0);
                        if (bt === null || tools > bt) bt = tools;
                        if (wt === null || tools < wt) wt = tools;
                        if (faults > wf) wf = faults;
                        var hyg = (s.cohesion || 0) + (s.procedure || 0);
                        if (bh === null || hyg > bh) bh = hyg;
                        if (wh === null || hyg < wh) wh = hyg;
                    }
                    maxTools += (bt || 0);
                    minTools += (wt || 0);
                    maxFaults += wf;
                    maxHyg += (bh || 0);
                    minHyg += (wh || 0);
                }
            }
            this._boundsCache[n] = { maxTools: maxTools, minTools: minTools, maxFaults: maxFaults, maxHyg: maxHyg, minHyg: minHyg };
            return this._boundsCache[n];
        }

        _updateBriefing(state) {
            /* the round to show is the one after the last round in history, so a render
               that runs before or after the framework advances the counter shows the same screen */
            var live = (window.mySimulation && window.mySimulation.state) || {};
            var hist = (state && state.history) || live.history || [];
            var played = hist.length;
            var finished = played >= this.ROUNDS.length;
            var idx = Math.min(played, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = currentLang();
            var tr = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var btns = document.querySelector('.chair-sim-actions');

            if (finished) {
                var donePanel = document.getElementById('decisionsPanel');
                if (donePanel) donePanel.innerHTML = '';
                if (btns) btns.style.display = 'none';
                var doneTitle = document.getElementById('momentTitle');
                if (doneTitle) doneTitle.textContent = tr('session_complete');
                var doneBrief = document.getElementById('briefingText');
                if (doneBrief) doneBrief.textContent = tr('session_complete_brief');
                return;
            }
            if (btns) btns.style.display = '';

            var titleEl = document.getElementById('momentTitle');
            if (titleEl) titleEl.textContent = (lang === 'es' && round.momentTitleEs) ? round.momentTitleEs : round.momentTitle;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = (lang === 'es' && round.briefingEs) ? round.briefingEs : round.briefing;

            var panel = document.getElementById('decisionsPanel');
            if (!panel) return;

            var saved = {};
            var stDecisions = (window.mySimulation && window.mySimulation.state
                && window.mySimulation.state.decisions) || {};
            round.decisions.forEach(function(d) {
                var existing = document.getElementById(d.id);
                var v = (existing && existing.value) || stDecisions[d.id] || '';
                if (v) saved[d.id] = v;
            });

            var html = '';
            round.decisions.forEach(function(d) {
                var dLabel = (lang === 'es' && d.labelEs) ? d.labelEs : d.label;
                html += '<div class="chair-sim-decision-row">';
                html += '<label class="chair-sim-decision-label" for="' + d.id + '">' + dLabel + '</label>';
                html += '<select id="' + d.id + '" class="chair-sim-decision-select form-control" required>';
                html += '<option value="">' + tr('select_placeholder') + '</option>';
                d.options.forEach(function(o) {
                    var oLabel = (lang === 'es' && o.labelEs) ? o.labelEs : o.label;
                    html += '<option value="' + o.value + '">' + oLabel + '</option>';
                });
                html += '</select>';
                html += '</div>';
            });
            panel.innerHTML = html;

            round.decisions.forEach(function(d) {
                if (!saved[d.id]) return;
                var sel = document.getElementById(d.id);
                if (!sel) return;
                var valid = d.options.some(function(o) { return String(o.value) === String(saved[d.id]); });
                if (valid) sel.value = saved[d.id];
            });
        }

        validateDecisions(decisions) {
            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var allFilled = true;

            round.decisions.forEach(function(d) {
                var sel = document.getElementById(d.id);
                if (sel && sel.value) {
                    decisions[d.id] = sel.value;
                } else {
                    allFilled = false;
                }
            });

            if (!allFilled) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var scoring = round.scoring;

            var deltas = {
                intrusion: 0, omission: 0, soleChannel: 0,
                cohesion: 0, procedure: 0,
                framing: 0, sequencing: 0, recusal: 0, after: 0
            };

            round.decisions.forEach(function(d) {
                var v = state.decisions[d.id];
                var s = scoring[d.id] && scoring[d.id][v];
                if (s) {
                    Object.keys(s).forEach(function(k) {
                        deltas[k] = (deltas[k] || 0) + s[k];
                    });
                }
            });

            var ds = state.domainState;
            ds.intrusions += deltas.intrusion;
            ds.omissions += deltas.omission;
            ds.soleChannel += deltas.soleChannel;
            ds.cohesion = Math.max(0, ds.cohesion + deltas.cohesion);
            ds.procedure = Math.max(0, ds.procedure + deltas.procedure);
            ds.framing += deltas.framing;
            ds.sequencing += deltas.sequencing;
            ds.recusal += deltas.recusal;
            ds.after += deltas.after;

            ds.framingHistory.push(ds.framing);
            ds.sequencingHistory.push(ds.sequencing);
            ds.recusalHistory.push(ds.recusal);
            ds.afterHistory.push(ds.after);
            ds.intrusionsHistory.push(ds.intrusions);
            ds.omissionsHistory.push(ds.omissions);
            ds.cohesionHistory.push(ds.cohesion);
            ds.procedureHistory.push(ds.procedure);

            var periodScore = this._composite(ds, idx + 1);
            ds.performance = { overallScore: periodScore };

            var roundToolsScore = deltas.framing + deltas.sequencing + deltas.recusal + deltas.after;
            var roundGrade = 'solid';
            if (deltas.intrusion >= 2 || deltas.soleChannel >= 2) roundGrade = 'shadow_ceo';
            else if (deltas.omission >= 2) roundGrade = 'rubber_stamp';
            else if (roundToolsScore >= 30 && deltas.intrusion === 0 && deltas.omission === 0) roundGrade = 'excellent';
            else if (roundToolsScore < 0) roundGrade = 'weak';

            var lang = currentLang();
            var momentTitle = (lang === 'es' && round.momentTitleEs) ? round.momentTitleEs : round.momentTitle;

            var self = this;
            setTimeout(function() {
                var live = (window.mySimulation && window.mySimulation.state) || state;
                self._updateBriefing(live);
            }, 500);

            return {
                period: state.currentPeriod,
                moment: momentTitle,
                intrusionsDelta: deltas.intrusion,
                omissionsDelta: deltas.omission,
                channelsDelta: deltas.soleChannel,
                cohesionDelta: deltas.cohesion,
                procedureDelta: deltas.procedure,
                framingDelta: deltas.framing,
                sequencingDelta: deltas.sequencing,
                recusalDelta: deltas.recusal,
                afterDelta: deltas.after,
                grade: roundGrade,
                overallScore: periodScore,
                score: periodScore
            };
        }

