                : function(k) { return k; };
            return {
                toolsChart: {
                    labels: [t('tool_framing'), t('tool_sequencing'), t('tool_recusal'), t('tool_after')],
                    datasets: [{
                        data: [ds.framing || 0, ds.sequencing || 0, ds.recusal || 0, ds.after || 0]
                    }]
                }
