        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var raw = (window.mySimulation && window.mySimulation.state
                && window.mySimulation.state.domainState) || {};
            var ds = {
                framing: raw.framing || 0, sequencing: raw.sequencing || 0,
                recusal: raw.recusal || 0, after: raw.after || 0,
                intrusions: raw.intrusions || 0, omissions: raw.omissions || 0,
                soleChannel: raw.soleChannel || 0,
                cohesion: typeof raw.cohesion === 'number' ? raw.cohesion : 100,
                procedure: typeof raw.procedure === 'number' ? raw.procedure : 100
            };
            var t = window.mySimulation.t.bind(window.mySimulation);
            var totalTools = ds.framing + ds.sequencing + ds.recusal + ds.after;

            var patternId = 'balanced';
            if (ds.intrusions >= 3) patternId = 'shadow_ceo';
            else if (ds.omissions >= 3) patternId = 'rubber_stamp';
            else if (ds.soleChannel >= 3) patternId = 'sole_channel';
            var dominant = t('pattern_' + patternId);


            var score100 = this._composite(ds, this.ROUNDS.length);
            var gradeId = this._bandOf(score100);
            var grade = t('grade_' + gradeId);

            var chosen = {};
            (history || []).forEach(function(rec) {
                var dd = (rec && rec.decisions) || {};
                Object.keys(dd).forEach(function(k) { chosen[k] = dd[k]; });
            });
            var lang = currentLang();
            var turningPoint = this._turningPoint(chosen, lang);

            /* named mistakes first (teaching.mistakes M1-M5), then the patterns */
            var insights = [];
            if (chosen.d_vote === 'force_vote') insights.push(t('ins_m_split'));
            if (chosen.d_advice === 'advise_personal') insights.push(t('ins_m_counsellor'));
            if (chosen.d_recusal === 'stay_careful') insights.push(t('ins_m_careful'));
            if (chosen.d_whitfield === 'accept_solo') insights.push(t('ins_m_activist'));
            if (chosen.d_dominicales === 'accept_bilateral_only') insights.push(t('ins_m_asymmetric'));
            if (ds.intrusions >= 2) insights.push(t('ins_intrusions'));
            if (ds.omissions >= 2) insights.push(t('ins_omissions'));
            if (ds.soleChannel >= 2) insights.push(t('ins_sole_channel'));
            if (ds.cohesion < 70) insights.push(t('ins_cohesion'));
            if (ds.procedure < 70) insights.push(t('ins_procedure'));
            if (ds.framing >= 25 && chosen.d_vote === 'reframe') insights.push(t('ins_framing'));
            if (ds.recusal >= 20 && chosen.d_recusal === 'recuse_formal') insights.push(t('ins_recusal'));
            if (ds.sequencing >= 25 && chosen.d_convocation === '48_72h' && chosen.d_whitfield === 'delegate_lid_ceo') insights.push(t('ins_sequencing'));
            if (ds.after >= 35 && chosen.d_acta === 'faithful' && chosen.d_insider === 'initiate_now' && chosen.d_committee === 'constitute_with_mandate') insights.push(t('ins_after'));
            if (insights.length === 0) insights.push(t('ins_clean'));
            insights = insights.slice(0, 5);

            return {
                grade: grade,
                gradeKey: gradeId,
                overallScore: score100,
                totalScore: score100,
                score: score100,
                composite: score100,
                performance: gradeId,
                performanceKey: gradeId,
                performanceLabel: grade,
                dominantPatternKey: patternId,
                dominantPattern: dominant,
                totalToolsScore: totalTools,
                framing: ds.framing,
                sequencing: ds.sequencing,
                recusal: ds.recusal,
                after: ds.after,
                intrusions: ds.intrusions,
                omissions: ds.omissions,
                soleChannel: ds.soleChannel,
                cohesion: ds.cohesion,
                procedure: ds.procedure,
                insights: insights,
                turningPoint: turningPoint
            };
        }

        formatCompletionMessage(summary) {
            if (!summary || summary.overallScore === undefined) return '';
            var t = window.mySimulation.t.bind(window.mySimulation);
            var esc = function(s) {
                return String(s === undefined || s === null ? '' : s)
                    .split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
            };
            var rows = [
                [t('tool_framing'), summary.framing],
                [t('tool_sequencing'), summary.sequencing],
                [t('tool_recusal'), summary.recusal],
                [t('tool_after'), summary.after]
            ].map(function(r) {
                return '<li><span>' + esc(r[0]) + '</span><strong>' + esc(r[1]) + '</strong></li>';
            }).join('');
            var faults = [
                [t('kpi_intrusions'), summary.intrusions],
                [t('kpi_omissions'), summary.omissions],
                [t('kpi_channels'), summary.soleChannel]
            ].map(function(r) {
                return '<li><span>' + esc(r[0]) + '</span><strong>' + esc(r[1]) + '</strong></li>';
            }).join('');
            var items = (summary.insights || []).map(function(x) {
                return '<li>' + esc(x) + '</li>';
            }).join('');
            return '<div class="chair-sim-debrief">'
                + '<h3>' + esc(t('debrief_title')) + '</h3>'
                + '<p class="chair-sim-debrief-band"><strong>' + esc(summary.performanceLabel)
